interaction_history.observation:
[
  {
    "id": 0,
    "knowledge": "Temperature Excursion Duration (TED)",
    "description": "The total time a shipment spends outside its required temperature range during transit.",
    "definition": "TED = \\sum_{i=1}^{n} t_i, \\text{where } t_i \\text{ is the duration in minutes of each individual temperature excursion event.}"
  },
  {
    "id": 1,
    "knowledge": "Temperature Excursion Severity Index (TESI)",
    "description": "Measures the severity of temperature excursions relative to product temperature requirements.",
    "definition": "TESI = TED \\times \\frac{|T_{max} - T_{allowed}| + |T_{min} - T_{allowed}|}{2}, \\text{where } T_{max} \\text{ and } T_{min} \\text{ are the maximum and minimum temperatures recorded during excursions, and } T_{allowed} \\text{ is the allowed temperature range midpoint.}"
  },
  {
    "id": 2,
    "knowledge": "Critical Temperature Exposure",
    "description": "Indicates when a product has been exposed to temperatures that may significantly impact product quality.",
    "definition": "An exposure event where the product temperature deviates more than 5\u00b0C from its specified temperature range for more than 60 consecutive minutes."
  },
  {
    "id": 3,
    "knowledge": "Route Risk Classification",
    "description": "Categorizes shipping routes based on their risk level for temperature excursions.",
    "definition": "Routes are classified as: 'Low Risk' (0-1 historical excursion events per 10 shipments), 'Medium Risk' (2-4 historical excursion events per 10 shipments), 'High Risk' (5+ historical excursion events per 10 shipments)."
  },
  {
    "id": 4,
    "knowledge": "GDP Certification Status",
    "description": "Illustrates the certification levels for carriers in Good Distribution Practice.",
    "definition": "Carriers can have one of the following certification statuses: 'None' (no certification), 'GDP' (Good Distribution Practice certified), 'CEIV Pharma' (IATA Center of Excellence for Independent Validators certification), or 'Both' (having both GDP and CEIV Pharma certifications). Null values indicate pending certification status verification."
  },
  {
    "id": 5,
    "knowledge": "Cold Chain Compliance Rate (CCCR)",
    "description": "Measures the percentage of shipments that maintained required temperature conditions throughout transit.",
    "definition": "CCCR = \\frac{N_{compliant}}{N_{total}} \\times 100\\%, \\text{where } N_{compliant} \\text{ is the number of shipments with zero temperature excursions, and } N_{total} \\text{ is the total number of shipments.}"
  },
  {
    "id": 6,
    "knowledge": "Temperature Sensitivity Tiers",
    "description": "Classifies pharmaceutical products based on their sensitivity to temperature variations.",
    "definition": "Products are classified into three sensitivity tiers: 'Low' (can tolerate up to 24 hours of minor temperature deviations), 'Medium' (can tolerate up to 8 hours of minor temperature deviations), 'High' (cannot tolerate temperature deviations beyond 2 hours)."
  },
  {
    "id": 7,
    "knowledge": "Tier 1 Cold Chain Products",
    "description": "Identifies the highest value and most temperature-sensitive pharmaceutical products.",
    "definition": "Products with both a 'High' temperature sensitivity and a value exceeding $100,000 USD."
  },
  {
    "id": 8,
    "knowledge": "Temperature Monitoring Gap",
    "description": "Indicates periods where temperature data is missing during transit.",
    "definition": "A period of over 15 minutes where no temperature data points were recorded in a shipment that should have continuous monitoring."
  },
  {
    "id": 9,
    "knowledge": "Product Storage Classifications",
    "description": "Standardized temperature ranges for pharmaceutical product storage.",
    "definition": "Four standard storage classifications: '2-8\u00b0C' (refrigerated), '-20\u00b0C' (frozen), '-70\u00b0C' (ultra-low temperature), and '15-25\u00b0C' (controlled room temperature)."
  },
  {
    "id": 10,
    "knowledge": "Cold Chain Monitoring Compliance Score (CCMCS)",
    "description": "Evaluates the completeness and quality of monitoring data for a shipment.",
    "definition": "CCMCS = 0.4 \\times GPS\\% + 0.4 \\times Temp\\% + 0.2 \\times (100 - ER), \\text{where GPS\\% is the GPS completeness percentage, Temp\\% is the percentage of expected temperature readings received, and ER is the error rate of readings.}"
  },
  {
    "id": 11,
    "knowledge": "Critical Monitoring Failure",
    "description": "Indicates when monitoring systems fail to provide sufficient data to assess product quality.",
    "definition": "Occurs when either GPS completeness falls below 80% or when temperature monitoring has gaps exceeding 30 minutes during transit."
  },
  {
    "id": 12,
    "knowledge": "On-Time Delivery Performance (OTDP)",
    "description": "Measures how accurately shipments meet their planned delivery times.",
    "definition": "OTDP = \\frac{actual\\_duration}{planned\\_duration} \\times 100\\%, \\text{where a value of 100\\% indicates exact on-time delivery, <100\\% is early, and >100\\% is late delivery.}"
  },
  {
    "id": 13,
    "knowledge": "Delivery Performance Classification",
    "description": "Categorizes delivery performance based on variance from expected delivery time.",
    "definition": "Shipments are classified as: 'Early' (>2 hours before scheduled time), 'On-Time' (within \u00b12 hours of scheduled time), 'Delayed' (2-24 hours after scheduled time), 'Severely Delayed' (>24 hours after scheduled time)."
  },
  {
    "id": 14,
    "knowledge": "Quality Agreement Status",
    "description": "Illustrates the current state of quality agreements between parties in the cold chain.",
    "definition": "Quality agreements can have the following statuses: 'Active' (current agreement in force), 'Expired' (agreement has lapsed), 'Pending' (agreement under review), or null (no formal agreement exists)."
  },
  {
    "id": 15,
    "knowledge": "Carrier Performance Index (CPI)",
    "description": "Measures the overall performance of a carrier across multiple shipments.",
    "definition": "CPI = 0.4 \\times CCCR + 0.3 \\times (100 - ATNR) + 0.2 \\times (100 - ASDI) + 0.1 \\times DPR, \\text{where CCCR is Cold Chain Compliance Rate, ATNR is Average Temperature Non-conformance Rate, ASDI is Average Shock and Damage Incidents, and DPR is Documentation Problem Rate.}"
  },
  {
    "id": 16,
    "knowledge": "Major Pharmaceutical Markets",
    "description": "Identifies the primary global pharmaceutical markets for cold chain distribution.",
    "definition": "Major pharmaceutical markets include: United States, European Union (specifically Germany, France, Italy, Spain, and United Kingdom), Japan, China, Brazil, India, and Russia."
  },
  {
    "id": 17,
    "knowledge": "High-Risk Shipping Origin-Destination Pairs",
    "description": "Identifies shipping routes that historically show elevated risks for cold chain integrity.",
    "definition": "Shipping lane combinations that either: 1) cross more than three climate zones, 2) involve more than two carrier transfers, 3) include countries with historical customs delays exceeding 48 hours, or 4) have previously documented temperature excursion rates above 15%."
  },
  {
    "id": 18,
    "knowledge": "Location Tracking States",
    "description": "Illustrates the possible states of location tracking systems during transit.",
    "definition": "Location tracking can be in one of these states: 'Active' (providing regular updates), 'Intermittent' (occasional gaps in tracking), 'Failed' (no longer providing location data), or null (tracking was not implemented for this shipment)."
  },
  {
    "id": 19,
    "knowledge": "Packing Integrity Risk Factor (PIRF)",
    "description": "Quantifies the risk of packaging failure based on product, route, and handling conditions.",
    "definition": "PIRF = \\frac{S \\times D \\times T}{P}, \\text{where S is the shock event count, D is the distance in thousands of km, T is a temperature factor (1 for 15-25\u00b0C, 1.5 for 2-8\u00b0C, 2 for -20\u00b0C, 2.5 for -70\u00b0C), and P is the packaging robustness factor (1-10, with 10 being most robust).}"
  },
  {
    "id": 20,
    "knowledge": "Shipment Risk Score (SRS)",
    "description": "A comprehensive risk assessment score for cold chain shipments.",
    "definition": "SRS = 0.3 \\times TESI + 0.25 \\times PIRF + 0.25 \\times (100 - CCMCS) + 0.2 \\times RRF, \\text{where TESI is Temperature Excursion Severity Index, PIRF is Packing Integrity Risk Factor, CCMCS is Cold Chain Monitoring Compliance Score, and RRF is Route Risk Factor (1-10 based on Route Risk Classification).}"
  },
  {
    "id": 21,
    "knowledge": "Regulatory Compliance Status Definitions",
    "description": "Explains the different compliance status classifications used in quality assessment.",
    "definition": "Compliance statuses are defined as: 'Compliant' (meets all regulatory requirements), 'Non-compliant' (fails to meet one or more critical requirements), 'Under Review' (compliance being assessed), or null (compliance status not yet determined)."
  },
  {
    "id": 22,
    "knowledge": "Temperature-Sensitive Product Categories",
    "description": "The main categories of pharmaceutical products requiring temperature-controlled transport.",
    "definition": "Temperature-sensitive product categories include: Vaccines, Biologics (including monoclonal antibodies and recombinant proteins), Blood Products (including plasma and platelets), and Insulin products."
  },
  {
    "id": 23,
    "knowledge": "Shock Event Significance Levels",
    "description": "Classifies impact events based on their potential to damage pharmaceutical products.",
    "definition": "Shock events are classified as: 'Minor' (unlikely to cause damage), 'Moderate' (potential to damage if repeated), 'Severe' (likely to cause damage to product or packaging), with null values indicating no shock monitoring was implemented."
  },
  {
    "id": 24,
    "knowledge": "Cold Chain Vehicle Qualification Status",
    "description": "Illustrates the validation levels of vehicles used in pharmaceutical transport.",
    "definition": "Vehicles can be classified as: 'Validated' (fully validated through performance and temperature mapping studies), 'Qualified' (basic qualification but not fully validated), 'Unqualified' (not formally qualified for pharmaceutical transport)."
  },
  {
    "id": 25,
    "knowledge": "Time In Range Percentage (TIRP)",
    "description": "Calculates the percentage of time a shipment's temperature stayed within required parameters.",
    "definition": "TIRP = \\frac{T_{total} - TED}{T_{total}} \\times 100\\%, \\text{where } T_{total} \\text{ is the total transit time and TED is the Temperature Excursion Duration.}"
  },
  {
    "id": 26,
    "knowledge": "Mean Kinetic Temperature (MKT)",
    "description": "A calculated temperature that expresses the overall effect of temperature fluctuations during storage or transit.",
    "definition": "MKT = \\frac{-\\Delta H/R}{\\ln\\left(\\frac{\\sum_{i=1}^{n} e^{-\\Delta H/RT_i}}{n}\\right)}, \\text{where } \\Delta H \\text{ is the activation energy (usually 83.144 kJ/mol for pharmaceuticals), R is the gas constant (8.3144 J/mol/K), and } T_i \\text{ is each temperature point in Kelvin.}"
  },
  {
    "id": 27,
    "knowledge": "Quality Risk Zones",
    "description": "Identifies risk levels for temperature-sensitive products based on excursion metrics.",
    "definition": "Quality risk zones are: 'Green Zone' (TIRP > 98% and no excursions > 30 min), 'Yellow Zone' (95% \u2264 TIRP \u2264 98% or any excursion 30-60 min), 'Red Zone' (TIRP < 95% or any excursion > 60 min)."
  },
  {
    "id": 28,
    "knowledge": "Humidity Sensitivity Categories",
    "description": "Classifies pharmaceutical products based on their sensitivity to humidity variations.",
    "definition": "Humidity sensitivity categories are: 'Not Sensitive' (can tolerate wide humidity variations), 'Moderately Sensitive' (can tolerate limited humidity variations), 'Highly Sensitive' (requires strict humidity control), with null values indicating humidity sensitivity not specified."
  },
  {
    "id": 29,
    "knowledge": "Premium Transport Container Types",
    "description": "Identifies specialized containers used for high-value pharmaceutical transport.",
    "definition": "Premium transport containers include: Envirotainer RAP e2, Envirotainer RKN e1, va-Q-tainer USx, CSafe RKN, DoKaSch Opticooler, and Sonoco ThermoSafe PharmaPort 360."
  },
  {
    "id": 31,
    "knowledge": "Pharmaceutical Stability Budget",
    "description": "The total allowable time a product can spend outside of ideal conditions before quality is compromised.",
    "definition": "The maximum cumulative duration (typically specified in hours or days) that a pharmaceutical product can experience conditions outside its labeled storage requirements without significant impact to its quality, safety, or efficacy. Null values indicate stability budget has not been determined for the product."
  },
  {
    "id": 32,
    "knowledge": "Stability Budget Consumption Rate (SBCR)",
    "description": "Measures how quickly a shipment is consuming its allocated stability budget during transit.",
    "definition": "SBCR = \\frac{TED}{SB_{total}} \\times 100\\%, \\text{where TED is the Temperature Excursion Duration and } SB_{total} \\text{ is the total stability budget allocated for the product.}"
  },
  {
    "id": 33,
    "knowledge": "Package Integrity Monitoring Systems",
    "description": "Identifies technologies used to monitor physical integrity of packages during transit.",
    "definition": "Package integrity monitoring systems include: Shock Indicators (mechanical devices that show when a package has received an impact), Tilt Indicators (show if a package was tilted beyond acceptable angles), Electronic Impact Recorders (provide detailed shock measurements), and Pressure Indicators (monitor pressure changes in sealed containers)."
  },
  {
    "id": 34,
    "knowledge": "Product Release Decision Framework",
    "description": "Structured approach for determining if temperature-sensitive products can be released for use after transport.",
    "definition": "A decision framework considering: 1) Presence of temperature excursions, 2) Stability data for specific excursion profiles, 3) Package integrity, 4) Product appearance, and 5) Analytical testing results if required. Products can be 'Released' (meets all criteria), 'Released with CAPA' (meets essential criteria but requires corrective action), 'Quarantined' (requires further investigation), or 'Rejected' (failed critical criteria)."
  },
  {
    "id": 35,
    "knowledge": "Qualification Status of Temperature Monitoring Devices",
    "description": "Indicates the validation level of monitoring devices used in pharmaceutical transport.",
    "definition": "Monitoring devices can be: 'Fully Qualified' (calibrated with NIST-traceable standards and validated for pharmaceutical use), 'Partially Qualified' (calibrated but not fully validated), 'Unqualified' (not formally qualified), with null values indicating qualification status is unknown."
  },
  {
    "id": 36,
    "knowledge": "Lane Risk Potential (LRP)",
    "description": "Quantifies the risk associated with a specific shipping route based on historical performance.",
    "definition": "LRP = \\frac{TE_{total} + SD_{total} + CD_{total}}{N_{shipments}}, \\text{where } TE_{total} \\text{ is the total count of temperature excursions, } SD_{total} \\text{ is the total count of shipping delays, } CD_{total} \\text{ is the total count of customs delays, and } N_{shipments} \\text{ is the number of shipments on that lane.}"
  },
  {
    "id": 37,
    "knowledge": "Storage Temperature Requirements for Biologics",
    "description": "Specifies the standard temperature storage requirements for biological pharmaceutical products.",
    "definition": "Most biologics require storage at either '2-8\u00b0C' (refrigerated) or '-20\u00b0C' (frozen), with certain specialized biologic products requiring '-70\u00b0C' (ultra-low temperature) storage. Room temperature (15-25\u00b0C) storage is rarely suitable for biologics unless specifically formulated for stability at those temperatures."
  },
  {
    "id": 38,
    "knowledge": "Last Mile Delivery Risk",
    "description": "Specific risks associated with the final stage of pharmaceutical product delivery.",
    "definition": "Last mile delivery risks include: Lack of temperature-controlled vehicles, Multiple stops increasing door-opening frequency, Variable driver training in handling procedures, Inconsistent receiving procedures at destinations, and Limited monitoring capabilities compared to main transport segments."
  },
  {
    "id": 39,
    "knowledge": "Security Incident Severity Scale",
    "description": "Categorizes security events during pharmaceutical transport by their severity.",
    "definition": "Security incidents are classified on a scale of 0-4: '0' (No security concerns), '1' (Minor procedural deviation), '2' (Moderate security concern without evidence of tampering), '3' (Clear evidence of attempted tampering), '4' (Confirmed breach with product access), with null values indicating security assessment was not performed."
  },
  {
    "id": 40,
    "knowledge": "Temperature Profile Categorization",
    "description": "Classifies the pattern of temperature readings during a shipment.",
    "definition": "Temperature profiles are categorized as: 'Stable' (minimal variations within range), 'Cyclic' (regular patterns of variation within range), 'Trend' (gradual increase or decrease over time), 'Excursion' (periods outside acceptable range), or 'Erratic' (unpredictable variations suggesting monitoring issues)."
  },
  {
    "id": 41,
    "knowledge": "Excursion Impact Assessment (EIA)",
    "description": "Evaluates the potential quality impact of temperature excursions on product.",
    "definition": "EIA = \\sum_{i=1}^{n} (|T_i - T_{limit}| \\times t_i), \\text{where } T_i \\text{ is the temperature during excursion } i, T_{limit} \\text{ is the nearest temperature limit (upper or lower), and } t_i \\text{ is the duration of excursion } i \\text{ in hours.}"
  },
  {
    "id": 42,
    "knowledge": "Primary Cold Chain Monitoring Authorities",
    "description": "Key regulatory bodies that oversee cold chain management for pharmaceuticals.",
    "definition": "Primary regulatory authorities for pharmaceutical cold chains include: FDA (US Food and Drug Administration), EMA (European Medicines Agency), MHRA (UK Medicines and Healthcare products Regulatory Agency), Health Canada, TGA (Australian Therapeutic Goods Administration), PMDA (Japanese Pharmaceuticals and Medical Devices Agency), and WHO (World Health Organization)."
  },
  {
    "id": 43,
    "knowledge": "Package Thermal Efficiency Rating",
    "description": "Measures how effectively a packaging system maintains internal temperature despite external conditions.",
    "definition": "Thermal efficiency rating is classified as: 'Basic' (<24 hours of protection), 'Standard' (24-48 hours of protection), 'Enhanced' (48-96 hours of protection), 'Extended' (>96 hours of protection)."
  },
  {
    "id": 44,
    "knowledge": "Risk-Based Monitoring Intensity",
    "description": "Determines appropriate monitoring frequency based on product risk profile.",
    "definition": "High-risk products (biologics, vaccines) require continuous temperature monitoring with 5-minute intervals, medium-risk products should have 15-minute intervals, and low-risk products can use 30-minute intervals, with null values in monitoring frequency indicating unplanned or non-standardized monitoring approaches."
  },
  {
    "id": 45,
    "knowledge": "Cold Chain Cost Efficiency Ratio (CCER)",
    "description": "Measures the relationship between cold chain protection costs and product value.",
    "definition": "CCER = \\frac{C_{monitoring} + C_{packaging} + C_{transport}}{V_{product}} \\times 100\\%, \\text{where } C_{monitoring}, C_{packaging}, C_{transport} \\text{ are the respective costs, and } V_{product} \\text{ is the product value.}"
  },
  {
    "id": 46,
    "knowledge": "Quality Management System Maturity Model",
    "description": "Framework for assessing the sophistication of a cold chain quality management system.",
    "definition": "QMS maturity levels range from Level 1 (Basic: minimal documentation and reactive approaches) to Level 5 (Optimized: fully integrated systems with continuous improvement). Intermediate levels include Level 2 (Developing: standard procedures established), Level 3 (Defined: processes are well-documented and followed), and Level 4 (Managed: processes are measured and controlled)."
  },
  {
    "id": 47,
    "knowledge": "Thermodynamic Stability Class",
    "description": "Categorizes pharmaceutical products based on their thermal stability characteristics.",
    "definition": "Products are classified as: Class A (highly stable, can tolerate brief temperature excursions with minimal degradation), Class B (moderately stable), Class C (limited stability, requires strict temperature control), and Class D (highly unstable, no temperature excursions permitted)."
  },
  {
    "id": 48,
    "knowledge": "Data Logger Reliability Score (DLRS)",
    "description": "Assesses the reliability of temperature monitoring devices based on historical performance.",
    "definition": "DLRS = 100 - (10 \\times F_r + 5 \\times F_d + 3 \\times F_c + 2 \\times F_b), \\text{where } F_r \\text{ is the rate of reading failures, } F_d \\text{ is the rate of download failures, } F_c \\text{ is the calibration drift rate, and } F_b \\text{ is the battery failure rate. All rates are per 100 deployments.}"
  },
  {
    "id": 49,
    "knowledge": "Acceptable Temperature Deviation Limits",
    "description": "Industry standards for tolerable temperature deviations during pharmaceutical transport.",
    "definition": "For refrigerated products (2-8\u00b0C): brief excursions (< 30 min) to 0-12\u00b0C may be acceptable; For frozen products (-20\u00b0C): brief excursions to -15\u00b0C may be acceptable; For ultra-frozen products (-70\u00b0C): brief excursions to -60\u00b0C may be acceptable; For controlled room temperature products (15-25\u00b0C): brief excursions to 10-30\u00b0C may be acceptable."
  },
  {
    "id": 50,
    "knowledge": "Last Mile Delivery Metrics",
    "description": "Key performance indicators specific to final stage pharmaceutical delivery.",
    "definition": "Key last mile metrics include: First Attempt Delivery Success Rate, Temperature Deviation Frequency, Receiver Wait Time, Documentation Completion Rate, and Handler Qualification Status."
  },
  {
    "id": 51,
    "knowledge": "Batch Release Critical Path Elements",
    "description": "The essential components required before a temperature-sensitive product batch can be released.",
    "definition": "Critical path elements include: Complete temperature history with no unexplained gaps, Confirmation that any excursions were within stability budgets, Intact security seals or acceptable explanation for compromised seals, Complete chain of custody documentation, and Acceptable visual inspection results."
  },
  {
    "id": 52,
    "knowledge": "Electronic Monitoring System Tiers",
    "description": "Classification of monitoring systems based on their capabilities and features.",
    "definition": "Electronic monitoring systems are classified as: Tier 1 (basic data loggers with manual download), Tier 2 (enhanced loggers with USB or Bluetooth download), Tier 3 (network-connected devices with real-time alerts), and Tier 4 (fully integrated IoT systems with predictive capabilities and automated interventions)."
  },
  {
    "id": 53,
    "knowledge": "Validation Documentation Requirements",
    "description": "The essential documentation needed to validate cold chain processes and equipment.",
    "definition": "Required validation documents include: Validation Master Plan, Risk Assessment, User Requirements Specification, Design Qualification, Installation Qualification, Operational Qualification, Performance Qualification, Temperature Mapping Studies, and Final Validation Report."
  },
  {
    "id": 54,
    "knowledge": "Serialization Maturity Model",
    "description": "Framework for assessing pharmaceutical tracking and tracing capabilities.",
    "definition": "Serialization maturity levels are: Level 0 (No serialization), Level 1 (Batch-level tracking only), Level 2 (Package-level serialization without systematic verification), Level 3 (Verified package-level serialization), and Level 4 (End-to-end serialized supply chain with real-time visibility)."
  },
  {
    "id": 55,
    "knowledge": "Monitoring Device Calibration Status",
    "description": "Indicates if temperature monitoring devices are properly calibrated for accurate readings.",
    "definition": "Calibration status includes: 'Current' (calibrated within required timeframe, typically 12 months), 'Expired' (calibration period has elapsed), 'Exempt' (single-use devices with factory calibration), with null values indicating calibration status is unknown or not documented."
  },
  {
    "id": 56,
    "knowledge": "GDP Corrective Action Categories",
    "description": "Standard categories for corrective actions in Good Distribution Practice.",
    "definition": "GDP corrective action categories include: Training Enhancement, Documentation Update, Process Modification, Equipment Upgrade, Supplier Management, Transport Adjustment, Monitoring Improvement, and Regulatory Compliance Actions."
  },
  {
    "id": 57,
    "knowledge": "Temperature Accuracy Impact Factor (TAIF)",
    "description": "Quantifies the potential error in product status assessment due to monitoring device accuracy limitations.",
    "definition": "TAIF = \\frac{|T_{max} - T_{upper}|}{A} + \\frac{|T_{min} - T_{lower}|}{A}, \\text{where } T_{max} \\text{ and } T_{min} \\text{ are the maximum and minimum recorded temperatures, } T_{upper} \\text{ and } T_{lower} \\text{ are the upper and lower temperature limits, and } A \\text{ is the stated accuracy of the monitoring device in \u00b0C.}"
  },
  {
    "id": 58,
    "knowledge": "Vehicle Temperature Monitoring Types",
    "description": "Methods used to monitor temperatures in transport vehicles.",
    "definition": "Vehicle temperature monitoring types include: 'Continuous' (uninterrupted monitoring throughout transport), 'Interval' (periodic checks at predetermined times), 'None' (no active monitoring), with null values indicating monitoring type was not specified in documentation."
  },
  {
    "id": 59,
    "knowledge": "Data Integrity Components",
    "description": "Essential elements that ensure cold chain data is reliable for decision-making.",
    "definition": "Data integrity components include the ALCOA+ principles: Attributable (traceable to individual/system), Legible (readable and permanent), Contemporaneous (recorded at time of activity), Original (source data or certified copy), Accurate (error-free), plus Complete (all data included), Consistent (expected sequence followed), Enduring (preserved for required period), and Available (accessible when needed)."
  }
]

[SYSTEM NOTE: Remaining action budget: 15.5/18]

[
  {
    "id": 0,
    "knowledge": "Annual Fund Outperformance",
    "description": "Calculates the excess return of a fund compared to its category benchmark for a given year.",
    "definition": "\text{Annual Fund Outperformance} = \text{Fund's annual return} - \text{Category's average annual return}"
  },
  {
    "id": 1,
    "knowledge": "Relative Expense Ratio",
    "description": "Measures the difference between a fund's net expense ratio and its benchmark's expense ratio.",
    "definition": "\text{Relative Expense} = \text{Fund's net expense ratio} - \text{Benchmark's expense ratio}"
  },
  {
    "id": 2,
    "knowledge": "Return on Cost (ROC)",
    "description": "Assesses the fund's one-year performance relative to its cost, indicating how much return is generated per unit of expense.",
    "definition": "ROC = \frac{\text{Fund's 1-year return}}{\text{Net expense ratio}}"
  },
  {
    "id": 3,
    "knowledge": "Yield-to-Expense Ratio (YTER)",
    "description": "Evaluates an income-generating fund's efficiency by comparing its dividend yield to its net expense ratio.",
    "definition": "YTER = \frac{\text{Fund's yield rate}}{\text{Net expense ratio}}"
  },
  {
    "id": 4,
    "knowledge": "Price Position in 52-Week Range",
    "description": "Calculates the current price's position within its 52-week high-low range as a percentage.",
    "definition": "\text{Position} = \frac{\text{Recent price} - \text{52-week low price}}{\text{52-week high price} - \text{52-week low price}} \times 100"
  },
  {
    "id": 5,
    "knowledge": "Short-Term Momentum Indicator",
    "description": "A technical indicator that signals short-term trend strength by comparing the 50-day and 200-day moving averages.",
    "definition": "\text{Momentum} = \text{50-day moving average} - \text{200-day moving average}"
  },
  {
    "id": 6,
    "knowledge": "Information Ratio (Simplified)",
    "description": "Measures a fund's risk-adjusted excess return over its benchmark, using volatility as the measure of risk.",
    "definition": "IR = \frac{\text{Fund's 3-year average return} - \text{Benchmark's 3-year average return}}{\text{Fund's 3-year volatility}}"
  },
  {
    "id": 7,
    "knowledge": "Positive Return Consistency",
    "description": "Calculates the percentage of a fund's historical years that have yielded positive returns.",
    "definition": "\text{Consistency} = \frac{\text{Number of years with positive returns}}{\text{number of positive years with positive returns} + \text{number if years with negative returns}} \times 100"
  },
  {
    "id": 8,
    "knowledge": "Cost-Adjusted Annual Outperformance",
    "description": "Evaluates a fund's performance by considering both its excess return over its category and its cost relative to its benchmark.",
    "definition": "A fund's performance is adjusted by combining its 'Annual Fund Outperformance' with its 'Relative Expense Ratio'. A higher positive outperformance and a lower (negative) relative expense are desirable."
  },
  {
    "id": 9,
    "knowledge": "Total Return Fund",
    "description": "Defines a fund that aims to provide both capital appreciation and income through dividends.",
    "definition": "A fund is classified as a Total Return Fund if it has both a non-zero allocation to stocks and a non-zero dividend yield."
  },
  {
    "id": 10,
    "knowledge": "Alpha Generator",
    "description": "A fund that has demonstrated an ability to outperform its benchmark on a risk-adjusted basis.",
    "definition": "A fund is considered an Alpha Generator if its 5-year alpha is greater than 0."
  },
  {
    "id": 11,
    "knowledge": "Market-Tracking Fund",
    "description": "A fund whose performance is highly correlated with its market benchmark.",
    "definition": "A fund is considered a Market-Tracking Fund if its 3-year R-squared value is greater than 90, indicating a strong correlation with its benchmark."
  },
  {
    "id": 12,
    "knowledge": "Low-Turnover Strategy",
    "description": "An investment strategy characterized by infrequent trading of portfolio holdings, often associated with long-term, passive, or buy-and-hold approaches.",
    "definition": "A fund employs a Low-Turnover Strategy if its annual portfolio turnover is less than 30%."
  },
  {
    "id": 13,
    "knowledge": "High-Conviction Portfolio",
    "description": "A portfolio where the manager allocates a significant portion of assets to a small number of their best ideas.",
    "definition": "A fund is considered to have a High-Conviction Portfolio if the weight of its single largest holding is greater than 8%."
  },
  {
    "id": 14,
    "knowledge": "Efficient Income Generator",
    "description": "A fund that provides a high dividend yield relative to its management cost.",
    "definition": "A fund is classified as an Efficient Income Generator if its 'Yield-to-Expense Ratio (YTER)' is greater than 15."
  },
  {
    "id": 15,
    "knowledge": "Consistent Outperformer",
    "description": "A fund that not only generates alpha but also consistently delivers positive annual returns.",
    "definition": "A fund is a Consistent Outperformer if it is an 'Alpha Generator' and has a 'Positive Return Consistency' score greater than 80."
  },
  {
    "id": 16,
    "knowledge": "Passive Alpha Generator",
    "description": "A rare type of fund that closely tracks a market benchmark but still manages to produce positive alpha.",
    "definition": "A fund is a Passive Alpha Generator if it is both a 'Market-Tracking Fund' and an 'Alpha Generator'."
  },
  {
    "id": 17,
    "knowledge": "Golden Cross Signal",
    "description": "A bullish technical signal indicating potential for a major rally, based on moving average trends.",
    "definition": "A Golden Cross Signal occurs for a fund when its 'Short-Term Momentum Indicator' is positive, suggesting its short-term average price has crossed above its long-term average price."
  },
  {
    "id": 18,
    "knowledge": "Geographic Focus",
    "description": "Classification of funds based on their primary geographic area of investment.",
    "definition": "Funds are categorized by their geographic scope, such as 'UNITED_STATES', 'International', 'Global', 'Pacific/Asia ex-Japan Stk', and 'Emerging Markets'."
  },
  {
    "id": 19,
    "knowledge": "High-Quality Credit Portfolio",
    "description": "A bond fund that primarily holds securities with very low credit risk.",
    "definition": "A fund is defined as having a High-Quality Credit Portfolio if the sum of its allocations to government, AAA, and AA rated bonds exceeds 60% of its total bond holdings."
  },
  {
    "id": 20,
    "knowledge": "Yield Rate",
    "description": "Illustrates the fund's annual dividend yield.",
    "definition": "Represents the annual dividend per share as a percentage of the share's price. A value of 0.02 signifies a 2% yield. This is a crucial metric for income-focused investors."
  },
  {
    "id": 21,
    "knowledge": "Turnover Ratio",
    "description": "Illustrates the fund's portfolio turnover.",
    "definition": "Measures how frequently assets within a fund are bought and sold. A ratio of 1.0 (100%) means the fund replaces its entire portfolio once per year. A low value (<0.3) suggests a buy-and-hold strategy, while a high value (>1.0) indicates active trading."
  },
  {
    "id": 22,
    "knowledge": "Beta",
    "description": "Illustrates the fund's market sensitivity (Beta).",
    "definition": "Measures a fund's volatility in relation to the overall market. Beta > 1 indicates the fund is more volatile than the market. Beta < 1 indicates it is less volatile. Beta = 1 implies its movement matches the market."
  },
  {
    "id": 23,
    "knowledge": "R-Squared",
    "description": "Illustrates the fund's correlation to its benchmark (R-squared).",
    "definition": "Represents the percentage of a fund's movements that can be explained by movements in its benchmark index. A value of 95 means that 95% of the fund's performance is attributable to the benchmark's performance."
  },
  {
    "id": 24,
    "knowledge": "Sharpe Ratio",
    "description": "Illustrates the fund's risk-adjusted return (Sharpe Ratio).",
    "definition": "Measures the fund's excess return per unit of total risk (volatility). A higher Sharpe Ratio is better. A ratio > 1 is generally considered good, > 2 is very good, and > 3 is excellent."
  },
  {
    "id": 25,
    "knowledge": "Duration",
    "description": "Illustrates a bond fund's interest rate sensitivity (Duration).",
    "definition": "Measures how much a bond fund's price is likely to change for every 1% change in interest rates. A duration of 7 years means the fund's price will likely fall by about 7% if interest rates rise by 1%."
  },
  {
    "id": 26,
    "knowledge": "Net Expense Ratio",
    "description": "Illustrates the fund's net annual cost (Expense Ratio).",
    "definition": "The annual fee charged to investors as a percentage of assets. A value of 0.005 corresponds to a 0.5% annual fee. Lower is generally better, as costs directly reduce returns."
  },
  {
    "id": 27,
    "knowledge": "Equity Weight",
    "description": "Illustrates the fund's allocation to stocks.",
    "definition": "The percentage of the fund's assets invested in equities (stocks). A value of 0.9 indicates that 90% of the fund is invested in stocks, suggesting a growth-oriented strategy."
  },
  {
    "id": 28,
    "knowledge": "Sector Weight",
    "description": "Illustrates the fund's concentration in a specific economic sector.",
    "definition": "The percentage of a fund's assets invested in a particular sector, like 'technology' or 'healthcare'. A high value, such as 0.4 (40%), indicates a significant bet on that sector's performance."
  },
  {
    "id": 29,
    "knowledge": "Credit Quality",
    "description": "Illustrates the credit quality of bond holdings.",
    "definition": "Indicates the creditworthiness of the bonds a fund holds. 'Government' is the highest quality. 'AAA' and 'AA' are considered high-grade investment quality. Ratings below 'BBB' are considered speculative or high-yield."
  },
  {
    "id": 30,
    "knowledge": "Performance-Cost Efficiency Score",
    "description": "Calculates a fund's efficiency by measuring its annual outperformance relative to its cost compared to peers.",
    "definition": "\text{PCES} = \frac{\text{Annual Fund Outperformance}}{\text{Relative Expense Ratio}}"
  },
  {
    "id": 31,
    "knowledge": "Momentum-Weighted Price Strength",
    "description": "A composite technical indicator that scores a fund based on its current price position, giving more weight to funds with stronger upward momentum.",
    "definition": "\text{MWPS} = \text{Price Position} \times (1 + \frac{\text{Momentum}}{\text{200-Day Moving Average}})"
  },
  {
    "id": 32,
    "knowledge": "Consistency-Adjusted Information Ratio",
    "description": "Refines the Information Ratio by factoring in the historical consistency of a fund's positive returns.",
    "definition": "\text{CAIR} = \text{Information Ratio} \times \frac{\text{Positive Return Consistency}}{100}"
  },
  {
    "id": 33,
    "knowledge": "Total Value Score",
    "description": "A holistic performance score combining risk-adjusted returns, cost-efficiency, and historical consistency.",
    "definition": "\text{TVS} = \\sqrt[3]{\text{Return on Cost} \times \text{Information Ratio} \times \text{Positive Return Consistency}}"
  },
  {
    "id": 34,
    "knowledge": "Active Manager Value",
    "description": "Quantifies the net value an active manager provides by subtracting the fund's relative cost from its demonstrated ability to generate risk-adjusted excess returns.",
    "definition": "\text{AMV} = \text{Information Ratio} - (\text{Relative Expense Ratio} \times 10)"
  },
  {
    "id": 35,
    "knowledge": "Quality-Income Score",
    "description": "A metric that assesses income-generating funds on both the efficiency and the credit quality of their yield.",
    "definition": "This score is the 'Yield-to-Expense Ratio' for a fund, but only applies if the fund also qualifies as a 'High-Quality Credit Portfolio'."
  },
  {
    "id": 36,
    "knowledge": "Composite Momentum Strength",
    "description": "A score that confirms a bullish technical trend by combining a positive momentum signal with the fund's price strength.",
    "definition": "\text{CMS} = \text{Short-Term Momentum Indicator} \times \text{Price Position in 52-Week Range}"
  },
  {
    "id": 37,
    "knowledge": "Net Yield Advantage",
    "description": "Calculates a fund's final yield advantage or disadvantage after accounting for its cost relative to peers.",
    "definition": "\text{NYA} = \text{Yield Rate} - \text{Relative Expense Ratio}"
  },
  {
    "id": 38,
    "knowledge": "Holistic Outperformance Metric",
    "description": "A comprehensive metric that blends a fund's raw outperformance with its risk-adjusted, cost-adjusted performance.",
    "definition": "\text{HOM} = \frac{\text{Annual Fund Outperformance} + \text{Cost-Adjusted Annual Outperformance}}{2}"
  },
  {
    "id": 39,
    "knowledge": "Risk-Return Efficiency Index",
    "description": "An index that evaluates how effectively a fund translates risk (volatility) into returns, adjusted for costs.",
    "definition": "\text{RREI} = \frac{\text{Return on Cost}}{\text{3-Year Volatility}}"
  },
  {
    "id": 40,
    "knowledge": "Elite Active Manager",
    "description": "Identifies a top-tier fund manager who generates consistent, risk-adjusted outperformance through a high-conviction, concentrated portfolio.",
    "definition": "A fund is run by an Elite Active Manager if it qualifies as a 'Consistent Outperformer' and maintains a 'High-Conviction Portfolio'."
  },
  {
    "id": 41,
    "knowledge": "Ideal Index Fund",
    "description": "Defines a fund that perfectly embodies the principles of passive investing: low cost, low trading, and tight benchmark tracking.",
    "definition": "A fund is an Ideal Index Fund if it is a 'Market-Tracking Fund', employs a 'Low-Turnover Strategy', and has a negative 'Relative Expense Ratio'."
  },
  {
    "id": 42,
    "knowledge": "Premier Income Fund",
    "description": "Identifies a superior income-focused fund that is not only efficient in generating yield but also prioritizes the safety of its underlying bond holdings.",
    "definition": "A fund is a Premier Income Fund if it is both an 'Efficient Income Generator' and has a 'High-Quality Credit Portfolio'."
  },
  {
    "id": 43,
    "knowledge": "Rebound Prospect",
    "description": "A fund that has recently underperformed but is showing strong technical signs of a potential turnaround in its price trend.",
    "definition": "A fund is a Rebound Prospect if its 'Annual Fund Outperformance' for the last reported year is negative, but it is currently showing a 'Golden Cross Signal'."
  },
  {
    "id": 44,
    "knowledge": "High-Fee Strategic Bet",
    "description": "Classifies a fund as an expensive, actively-managed portfolio that deviates significantly from market benchmarks, representing a pure play on manager skill.",
    "definition": "A fund is a High-Fee Strategic Bet if its 'Relative Expense Ratio' is positive and it does not qualify as a 'Market-Tracking Fund'."
  },
  {
    "id": 45,
    "knowledge": "Focused Alpha Leader",
    "description": "An actively managed fund that successfully generates excess returns by taking concentrated bets on its best ideas.",
    "definition": "A fund is a Focused Alpha Leader if it is classified as both an 'Alpha Generator' and a 'High-Conviction Portfolio'."
  },
  {
    "id": 46,
    "knowledge": "Reliable Core Holding",
    "description": "Identifies a fund suitable as a core portfolio holding due to its history of steady returns and its balanced approach to providing both growth and income.",
    "definition": "A fund is a Reliable Core Holding if it is a 'Consistent Outperformer' and is also structured as a 'Total Return Fund'."
  },
  {
    "id": 47,
    "knowledge": "Contrarian Value Play",
    "description": "A fund that is currently out of favor with the market but is managed with a patient, low-cost, long-term strategy, making it a potential value investment.",
    "definition": "A fund is a Contrarian Value Play if its Price Position in 52-Week Range is below 25%, it follows a Low-Turnover Strategy, and its Relative Expense Ratio is negative."
  },
  {
    "id": 48,
    "knowledge": "Global Alpha Specialist",
    "description": "An investment fund that specializes in a non-US market and has demonstrated a skillful ability to outperform its relevant benchmark.",
    "definition": "A fund is a Global Alpha Specialist if it is an 'Alpha Generator' and its 'Geographic Focus' is anything other than 'UNITED_STATES' or 'US'."
  },
  {
    "id": 49,
    "knowledge": "High-Cost Underperformer",
    "description": "Flags a fund that is both more expensive than its peers and has failed to outperform its category, representing poor value for investors.",
    "definition": "A fund is a High-Cost Underperformer if it has a positive 'Relative Expense Ratio' and a negative 'Annual Fund Outperformance'."
  },
  {
    "id": 50,
    "knowledge": "Appraisal Ratio",
    "description": "Measures a fund manager's skill in stock selection by calculating the alpha generated per unit of specific, unsystematic risk taken.",
    "definition": "\text{Appraisal Ratio} = \frac{\text{3-Year Alpha}}{\text{Unsystematic Risk}}, \text{ where Unsystematic Risk} = \text{3-Year Volatility} \times \\sqrt{1 - \text{3-Year R-Squared}}"
  },
  {
    "id": 51,
    "knowledge": "Composite Valuation Score",
    "description": "Calculates a single score representing a fund's valuation attractiveness by averaging the inverted values of its key price-to-metric ratios.",
    "definition": "CVS = \frac{1}{4} \times (\frac{1}{\text{P/E Ratio}} + \frac{1}{\text{P/S Ratio}} + \frac{1}{\text{P/B Ratio}} + \frac{1}{\text{P/CF Ratio}})"
  },
  {
    "id": 52,
    "knowledge": "Active Management Footprint",
    "description": "Quantifies the degree of a fund's active management by measuring its deviation from the benchmark relative to its trading activity.",
    "definition": "AMF = \frac{1 - \text{3-Year R-Squared}}{\text{Turnover Ratio}}"
  },
  {
    "id": 53,
    "knowledge": "Cost-Adjusted Alpha",
    "description": "Calculates the fund's alpha after penalizing it for having higher expenses than its benchmark, revealing the true value added by the manager.",
    "definition": "CAA = \text{3-Year Alpha} - \text{Relative Expense Ratio}"
  },
  {
    "id": 54,
    "knowledge": "Momentum-Adjusted Information Ratio",
    "description": "A dynamic version of the Information Ratio that is enhanced by the fund's current price momentum, rewarding funds that are outperforming on a risk-adjusted basis and are also in a strong uptrend.",
    "definition": "MAIR = \text{Information Ratio (Simplified)} \times (1 + \frac{\text{Short-Term Momentum Indicator}}{\text{200-Day Moving Average}})"
  },
  {
    "id": 55,
    "knowledge": "Secure Income Efficiency Score",
    "description": "A composite score for income funds that measures yield-generating efficiency while heavily weighting for the credit safety of the underlying assets.",
    "definition": "SIES = \text{Yield-to-Expense Ratio} \times (\text{Allocation to High-Quality Credit})"
  },
  {
    "id": 56,
    "knowledge": "Manager Skill Ratio",
    "description": "Measures the amount of alpha a fund manager generates for each dollar of fee charged to investors.",
    "definition": "MSR = \frac{\text{3-Year Alpha}}{\text{Net Expense Ratio}}"
  },
  {
    "id": 57,
    "knowledge": "Capital Preservation Index",
    "description": "Scores a fund on its ability to protect capital by combining its history of avoiding down years with its ability to stay above its 52-week lows.",
    "definition": "CPI = (\frac{1}{1 + \text{Negative Years}}) \times (1 - \frac{\text{52-Week Low} - \text{Current Price}}{\text{52-Week Low}})"
  },
  {
    "id": 58,
    "knowledge": "Portfolio Liquidity Pressure",
    "description": "Estimates the potential market impact of a fund's trading activity by comparing its annual turnover to its average daily trading volume.",
    "definition": "PLP = \frac{\text{Net Worth} \times \text{Turnover Ratio}}{\text{Average Daily Volume (3M) } \times 252}"
  },
  {
    "id": 59,
    "knowledge": "Growth-Value Spectrum Score",
    "description": "A quantitative factor score that places a fund on a spectrum from deep value to high growth based on the interplay of its Price-to-Earnings and Price-to-Book ratios.",
    "definition": "\text{GVS Score} = \\ln(\frac{\text{P/E Ratio}}{\text{P/B Ratio}})"
  },
  {
    "id": 60,
    "knowledge": "Closet Indexer",
    "description": "A fund that is marketed as an active fund and charges higher fees, but its portfolio holdings and performance closely track a benchmark index.",
    "definition": "A fund is identified as a Closet Indexer if it is a 'Market-Tracking Fund' but has a positive 'Relative Expense Ratio'."
  },
  {
    "id": 61,
    "knowledge": "Strategic Beta Fund",
    "description": "An investment fund that occupies the middle ground between passive and active management, using a rules-based system to target specific factors or market segments beyond simple market-cap weighting.",
    "definition": "A fund is classified as Strategic Beta if it employs a 'Low-Turnover Strategy' but is explicitly not a 'Market-Tracking Fund'."
  },
  {
    "id": 62,
    "knowledge": "Fallen Angel",
    "description": "A once highly-regarded fund that has seen a significant decline in its performance and ability to generate alpha.",
    "definition": "A fund is a Fallen Angel if it was previously considered a 'Consistent Outperformer' but its most recent 3-year alpha is now negative."
  },
  {
    "id": 63,
    "knowledge": "Quality-Growth at a Reasonable Price (Q-GARP)",
    "description": "An investment style that seeks to own high-quality, growing companies without overpaying. These funds blend quality, growth, and value characteristics.",
    "definition": "A fund follows a Q-GARP strategy if it is a 'Consistent Outperformer' and has a 'Composite Valuation Score' in the top 50th percentile of its category."
  },
  {
    "id": 64,
    "knowledge": "High-Conviction Value Investor",
    "description": "A fund manager who adheres to a strict value discipline, evidenced by attractive valuation metrics, while taking large, concentrated positions in their best ideas.",
    "definition": "A fund is a High-Conviction Value Investor if it is a 'High-Conviction Portfolio' and has a 'Composite Valuation Score' in the top 25th percentile of its category."
  },
  {
    "id": 65,
    "knowledge": "Efficient Core Holding",
    "description": "An ideal fund for the core of a portfolio, characterized by extremely low costs, tight benchmark tracking, and proven efficiency in translating assets into returns.",
    "definition": "A fund is an Efficient Core Holding if it qualifies as an 'Ideal Index Fund' and also exhibits a high 'Return on Cost (ROC)'."
  },
  {
    "id": 66,
    "knowledge": "Momentum-Driven Growth Fund",
    "description": "A fund that specifically targets high-growth companies that are also exhibiting strong, positive price momentum in the market.",
    "definition": "A fund is a Momentum-Driven Growth Fund if its 'Growth-Value Spectrum Score' indicates a growth tilt and it is also currently signaling a 'Golden Cross Signal'."
  },
  {
    "id": 67,
    "knowledge": "Defensive Anchor",
    "description": "A fund suitable for mitigating portfolio volatility, characterized by low market sensitivity and a strong track record of preserving capital.",
    "definition": "A fund is a Defensive Anchor if its 3-year Beta is less than 0.75 and it has a high 'Capital Preservation Index' score."
  },
  {
    "id": 68,
    "knowledge": "True Active Differentiator",
    "description": "A fund that demonstrates genuine active management through significant deviation from its benchmark, skilled stock selection, and a high-conviction approach.",
    "definition": "A fund is a True Active Differentiator if it has 'Active Management Footprint' > 0.5, 'Appraisal Ratio' > 0.2, and is also a 'High-Conviction Portfolio'."
  },
  {
    "id": 69,
    "knowledge": "Speculative Turnaround Play",
    "description": "A high-risk, high-reward fund that has been performing poorly and is costly, but is showing technical signs of a potential, albeit uncertain, recovery.",
    "definition": "A fund is a Speculative Turnaround Play if it is a 'High-Cost Underperformer' but has recently triggered a 'Golden Cross Signal'."
  },
  {
    "id": 70,
    "knowledge": "Year-over-Year Performance Trend",
    "description": "Calculates the change in a fund's performance relative to its category from one year to the next.",
    "definition": "\\Delta_{YoY} = \text{Outperformance}{\text{current year}} - \text{Outperformance}{\text{previous year}}"
  },
  {
    "id": 71,
    "knowledge": "Category Average Duration",
    "description": "Calculates the average duration for all funds within the same investment category.",
    "definition": "\bar{D}c = \frac{\\sum \text{Fund Durations}}{\text{Total number of funds}} \text{ for a given category.}"
  },
  {
    "id": 72,
    "knowledge": "Duration Advantage",
    "description": "Measures how much lower a fund's duration is compared to its category average.",
    "definition": "D{\text{adv}} = \text{Category Average Duration} - \text{Fund's Duration}"
  },
  {
    "id": 73,
    "knowledge": "Average Upside Outperformance",
    "description": "Measures a fund's average outperformance during years when its category had positive returns.",
    "definition": "\bar{O}{\text{up}} = \text{Average 'Annual Fund Outperformance' during years with positive category returns.}"
  },
  {
    "id": 74,
    "knowledge": "Average Downside Outperformance",
    "description": "Measures a fund's average outperformance during years when its category had negative returns. A smaller negative number indicates better downside protection.",
    "definition": "\bar{O}{\text{down}} = \text{Average 'Annual Fund Outperformance' during years with non-positive category returns.}"
  },
  {
    "id": 75,
    "knowledge": "Capture Differential",
    "description": "Calculates the difference between a fund's average outperformance in up markets versus down markets, indicating its overall adaptability.",
    "definition": "C_{\text{diff}} = \text{Average Upside Outperformance} - \text{Average Downside Outperformance}"
  },
  {
    "id": 76,
    "knowledge": "Average Daily Value Traded (3M)",
    "description": "Calculates the average monetary value of a fund's shares traded daily over the last 3 months.",
    "definition": "\text{ADVT}{3M} = \text{Average daily volume (3M)} \times \text{Average share price (e.g., 200-day MA)}"
  },
  {
    "id": 77,
    "knowledge": "Beta Drift",
    "description": "Measures the change in a fund's sensitivity to market movements over time.",
    "definition": "\\Delta{\beta} = \text{Beta}{\text{1st Period}} - \text{Beta}{\text{2nd Period}}"
  },
  {
    "id": 78,
    "knowledge": "R-Squared Drift",
    "description": "Measures the change in a fund's performance correlation with its benchmark over time.",
    "definition": "\\Delta_{R^2} = R^2_{\text{1st Period}} - R^2_{\text{2nd Period}}"
  },
  {
    "id": 79,
    "knowledge": "Style Drift",
    "description": "A classification of how a fund's investment style has changed by comparing its recent risk characteristics (Beta, R-Squared) to its long-term history.",
    "definition": "A fund is considered to have drifted if its absolute Beta change exceeds 0.15 or its absolute R-Squared change exceeds 10."
  },
  {
    "id": 80,
    "knowledge": "Composite Score",
    "description": "A normalized score that averages a fund's percentile rank across multiple key performance and cost metrics, allowing for peer-group comparison.",
    "definition": "\text{Score} = \frac{\text{Percentile Rank}(\text{5Y Alpha}) + \text{Percentile Rank}(\text{3Y Sharpe}) + \text{Percentile Rank}(\text{Inverse Net Expense})}{3}"
  },
  {
    "id": 81,
    "knowledge": "Category Dominator",
    "description": "Identifies the single best-performing fund within an investment category based on a multi-factor composite score.",
    "definition": "The fund with the highest 'Composite Score' within its investment category, provided the category contains at least 10 funds."
  },
  {
    "id": 82,
    "knowledge": "Alpha-Turnover Slope",
    "description": "Calculates the slope of the linear regression line between a fund's alpha (dependent variable, Y) and its turnover ratio (independent variable, X).",
    "definition": "\beta_{\\alpha, T} = \text{Slope of regression}(\text{3-Year Alpha}, \text{Turnover Ratio})"
  },
  {
    "id": 83,
    "knowledge": "Fit Quality",
    "description": "Measures how well the turnover ratio explains the variation in alpha in the regression model.",
    "definition": "R^2 = \text{R-squared of regression}(\text{3-Year Alpha}, \text{Turnover Ratio})"
  },
  {
    "id": 85,
    "knowledge": "Median 1-Year Return",
    "description": "Calculates the median (50th percentile) of the 1-year returns for a group of funds.",
    "definition": "M = \text{The 50th percentile of 1-year returns for a specified group of funds.}"
  },
  {
    "id": 86,
    "knowledge": "Wasted Fee Amount",
    "description": "The total dollar amount of fees paid by investors in a Closet Indexer fund that are in excess of the benchmark's expense ratio.",
    "definition": "WFA = (\text{Net Expense Ratio} - \text{Benchmark Expense Ratio}) \times \text{Net Worth}"
  },
  {
    "id": 87,
    "knowledge": "Family Sector Concentration Profile",
    "description": "An analytical profile that identifies the single economic sector a fund family has the highest average allocation to, across all its funds.",
    "definition": "For each fund family, this profile is the economic sector with the highest average weight across all of the family's funds."
  },
  {
    "id": 88,
    "knowledge": "Top-Tier Family",
    "description": "A classification for a fund family that exhibits desirable risk-return characteristics, specifically low market risk and a proven ability to generate alpha.",
    "definition": "A fund family is 'Top-Tier' if its average 3-year beta is less than 1.0 and it manages 5 or more alpha-generating funds."
  }
]

