  {
    "id": 6,
    "knowledge": "Size Compatibility Score",
    "description": "A score that assesses the physical size match between a donor and recipient, primarily using Body Mass Index (BMI).",
    "definition": "A score derived from the ratio of donor and recipient BMI. Formula: $S_{size} = 1 - |\\frac{BMI_{donor}}{BMI_{recipient}} - 1|$."
  },
  {
    "id": 7,
    "knowledge": "Age Compatibility Score",
    "description": "A score evaluating the suitability of a donor's age relative to the recipient's, considering the Donor-Recipient Age Difference.",
    "definition": "A normalized score based on the Donor-Recipient Age Difference. Formula: $S_{age} = e^{-0.03 \\times |Age_{recipient} - Age_{donor}|}$, using a standard scaling factor."
  },
  {
    "id": 8,
    "knowledge": "Logistical Feasibility Index",
    "description": "Calculates an index representing the logistical viability of a transplant, considering distance and expected organ preservation time.",
    "definition": "A score combining geographic distance and Total Ischemia Time. Formula: $I_{logistics} = (\\frac{700}{Distance_{km}}) + (\\frac{300}{T_{ischemia\\_mins}})$"
  },
  {
    "id": 9,
    "knowledge": "Renal Function Score",
    "description": "A composite score to evaluate a donor's kidney health based on key indicators.",
    "definition": "A score calculated from the donor's Estimated Glomerular Filtration Rate (eGFR) and serum creatinine (Cr) level. Formula: $S_{renal} = (1.0 \\times eGFR) - (10.0 \\times Cr)$."
  },
  {
    "id": 10,
    "knowledge": "Immunological Compatibility Score",
    "description": "A comprehensive score assessing the immunological match, factoring in blood type and HLA differences.",
    "definition": "A weighted score based on ABO blood type compatibility status and the HLA Mismatch Score. Formula: $S_{immune} = 0.6 \\times I_{ABO} + 0.4 \\times (1 - \\frac{S_{mismatch}}{6})$, where $I_{ABO}$ is 1 for compatible, 0 otherwise."
  },
  {
    "id": 11,
    "knowledge": "Quality-Adjusted Life Year (QALY)",
    "description": "A measure of disease burden, including both the quality and the quantity of life lived.",
    "definition": "Calculated by multiplying the years of life by a quality-of-life score. Formula: $QALY = Years_{life} \\times Quality_{score}$"
  },
  {
    "id": 12,
    "knowledge": "Cost-Effectiveness Ratio (CER)",
    "description": "Calculates the cost per unit of health outcome, often using Quality-Adjusted Life Year (QALY).",
    "definition": "The ratio of the net cost of an intervention to its net health gain. Formula: $CER = \\frac{Cost_{net}}{QALY_{gained}}$"
  },
  {
    "id": 13,
    "knowledge": "Expected Graft Survival (EGS) Score",
    "description": "Predicts the probability of a transplanted organ functioning successfully over a specific period.",
    "definition": "A predictive score based on factors like the Immunological Compatibility Score and donor age. Formula: $EGS = \\frac{1}{1 + e^{-(-0.5 + 1.5 S_{immune} - 0.02 Age_{donor})}}$"
  },
  {
    "id": 14,
    "knowledge": "Patient Urgency Score",
    "description": "A score that quantifies the urgency of a recipient's need for a transplant.",
    "definition": "A composite score based on the recipient's medical urgency status and their Recipient Wait Time Ratio. Formula: $S_{urgency} = 0.7 \\times Status_{medical} + 0.3 \\times R_{wait}$"
  },
  {
    "id": 15,
    "knowledge": "Center Performance Score",
    "description": "A score evaluating a transplant center's performance based on its experience and patient outcomes.",
    "definition": "A weighted average of a center's transplant volume and its post-transplant success rates. Formula: $S_{center} = 0.6 \\times V_{transplants} + 0.4 \\times R_{success}$"
  },
  {
    "id": 16,
    "knowledge": "Surgical Risk Score",
    "description": "A score assessing the risk associated with the transplant surgery itself.",
    "definition": "A composite score derived from the recipient's comorbidities and the inherent complexity of the surgical procedure. Formula: $S_{surgical} = 0.6 \\times N_{comorbidities} + 0.4 \\times C_{procedure}$, where components are normalized."
  },
  {
    "id": 17,
    "knowledge": "Composite Allocation Score",
    "description": "A comprehensive score used to rank recipients for organ allocation, integrating multiple key factors.",
    "definition": "A weighted sum of the Patient Urgency Score, Immunological Compatibility Score, and Expected Graft Survival (EGS) Score. Formula: $S_{allocation} = 0.5 S_{urgency} + 0.25 S_{immune} + 0.25 EGS$"
  },
  {
    "id": 18,
    "knowledge": "Resource Utilization Index",
    "description": "An index that estimates the expected consumption of medical resources for a transplant case.",
    "definition": "A calculated index based on the Surgical Risk Score and expected length of hospital stay. Formula: $I_{resource} = S_{surgical} \\times Days_{stay}$"
  },
  {
    "id": 19,
    "knowledge": "Readmission Risk Index",
    "description": "A predictive index for the likelihood of a patient being readmitted to the hospital post-transplant.",
    "definition": "A risk index calculated from the number of pre-existing medical conditions and the Surgical Risk Score. Formula: $I_{readmission} = 0.1 + (0.05 \\times N_{conditions}) + (0.2 \\times S_{surgical})$"
  },
  {
    "id": 20,
    "knowledge": "ABO Blood Type Compatibility",
    "description": "Defines the rules for matching blood types between an organ donor and recipient to prevent hyperacute rejection.",
    "definition": "A fundamental matching rule where recipient blood type determines acceptable donor types. Type O is the universal donor; Type AB is the universal recipient. Type A can receive from A and O. Type B can receive from B and O."
  },
  {
    "id": 21,
    "knowledge": "Cold Ischemia",
    "description": "The period during which a harvested organ is kept cold to preserve it, starting from when its blood supply is cut off until it is transplanted.",
    "definition": "A state of organ preservation where metabolic activity is slowed by cooling, typically to around 4\u00b0C, to minimize tissue damage while outside the body. This is a critical factor in transplant success."
  },
  {
    "id": 22,
    "knowledge": "Human Leukocyte Antigen (HLA) Typing",
    "description": "The process of identifying specific HLA protein markers on a person's cells to match a donor with a recipient for transplantation.",
    "definition": "A genetic test that identifies a person's unique HLA markers. A closer HLA match between a donor and recipient reduces the risk of the recipient's immune system attacking, or rejecting, the transplanted organ."
  },
  {
    "id": 23,
    "knowledge": "Panel Reactive Antibody (PRA)",
    "description": "A test that measures the level of pre-existing antibodies in a recipient's blood against common HLA antigens, indicating their sensitization level.",
    "definition": "A measure of a recipient's sensitization to foreign HLA antigens, represented by the `pra_score`[cite: 36]. For matching purposes, a recipient with a `pra_score` of 80 or higher is defined as having a 'high PRA score', indicating a state of high immunological sensitization."
  },
  {
    "id": 24,
    "knowledge": "Crossmatch Test",
    "description": "A final compatibility test performed just before transplant surgery to ensure the recipient has no pre-formed antibodies against the specific donor's tissues.",
    "definition": "A laboratory test that directly mixes the recipient's serum with the donor's lymphocytes. A 'positive' Crossmatch Test indicates the presence of donor-specific antibodies and is a contraindication to transplantation, as it predicts immediate organ rejection."
  },
  {
    "id": 25,
    "knowledge": "Medical Urgency Status",
    "description": "A classification system used to prioritize patients on the transplant waiting list based on their immediate need and risk of mortality.",
    "definition": "A tiered system that reflects how critically ill a patient is. For calculation purposes, statuses are mapped to numerical values: Status 1A is assigned a value of 5, Status 1B is 4, Status 2 is 3, and Status 3 is 2. All other statuses are assigned a value of 1."
  },
  {
    "id": 26,
    "knowledge": "Donor-Specific Antibodies (DSA)",
    "description": "Antibodies in a recipient's blood that are specifically directed against a particular donor's HLA antigens.",
    "definition": "The presence of these antibodies is identified by a positive Crossmatch Test. They pose a significant risk for antibody-mediated rejection of the transplanted organ."
  },
  {
    "id": 27,
    "knowledge": "High-Risk Donor",
    "description": "An organ donor who has a history of certain medical conditions or behaviors that may increase the risk of disease transmission or poorer graft function in the recipient.",
    "definition": "A donor category defined by criteria such as a history of communicable diseases (e.g., Hepatitis C, HIV), malignancy, or high-risk social behaviors (e.g., intravenous drug use). The use of organs from a High-Risk Donor requires careful evaluation and informed consent."
  },
  {
    "id": 28,
    "knowledge": "Graft Survival",
    "description": "Refers to the period of time a transplanted organ continues to function properly within the recipient's body.",
    "definition": "A key outcome measure in transplantation. Successful Graft Survival means the organ is performing its intended biological functions without signs of rejection or failure."
  },
  {
    "id": 29,
    "knowledge": "Immunological Sensitization",
    "description": "A state where a recipient has a high level of pre-formed antibodies, making it difficult to find a compatible donor.",
    "definition": "A clinical state where a recipient is considered highly sensitized to potential donors. This condition is formally defined as having a Panel Reactive Antibody (PRA) score of 80 or greater. This high level of sensitization significantly complicates the matching process by severely limiting the number of compatible donors."
  },
  {
    "id": 30,
    "knowledge": "Static Cold Storage",
    "description": "The most common method of organ preservation, where the organ is flushed with a cold preservation solution and stored on ice.",
    "definition": "A preservation technique that relies on hypothermia to reduce the organ's metabolic rate and oxygen demand during transport, minimizing tissue damage during Cold Ischemia."
  },
  {
    "id": 31,
    "knowledge": "Optimal Donor-Recipient Match",
    "description": "An ideal pairing of a donor and recipient that meets a strict set of criteria to maximize the probability of long-term transplant success.",
    "definition": "An ideal match defined by meeting three specific, stringent criteria simultaneously: 1) Full ABO Blood Type Compatibility. 2) An HLA Mismatch Score of exactly 0. 3) A Size Compatibility Score within the inclusive range of [0.9, 1.1]. A pairing that satisfies all three conditions is classified as an Optimal Donor-Recipient Match."
  },
  {
    "id": 32,
    "knowledge": "Anoxia",
    "description": "A donor's cause of death due to complete oxygen deprivation, which can affect organ quality.",
    "definition": "A donor's cause of death resulting from a complete lack of oxygen. [cite_start]Within the database, this specific cause is recorded as 'Anoxia' in the donor's cause of death description (`don_co_desc` [cite: 15]). This factor is critical for assessing the viability of oxygen-sensitive organs, such as the heart and kidneys."
  },
  {
    "id": 33,
    "knowledge": "Comorbidity",
    "description": "The presence of one or more additional diseases or conditions co-occurring with a primary disease or condition.",
    "definition": "In transplantation, a recipient's pre-existing conditions (e.g., diabetes, heart disease) are considered comorbidities. They can increase the complexity and risk of the transplant procedure."
  },
  {
    "id": 34,
    "knowledge": "Allocation Policy",
    "description": "The specific versioned set of rules governing organ distribution, used to prioritize recipients.",
    "definition": "The precise set of rules used for organ distribution, identified by a unique version string in the `allc_pol_vers` field, such as 'v2.7'[cite: 73]. Each policy embodies a strict hierarchy of rules. As a formal example, a given policy stipulates that Medical Urgency Status is the primary sorting criterion; for recipients with an identical urgency status, the one with a lower HLA Mismatch Score receives higher priority."
  },
  {
    "id": 35,
    "knowledge": "Informed Consent",
    "description": "The process by which a patient, after understanding the risks and benefits, voluntarily agrees to a medical procedure.",
    "definition": "A critical ethical and legal requirement in transplantation where the recipient (or their proxy) must be fully informed about all aspects of the surgery, including the use of organs from a High-Risk Donor, before giving permission."
  },
  {
    "id": 36,
    "knowledge": "Regional Allocation Priority",
    "description": "A core principle within transplant allocation that prioritizes local matches to enhance fairness and clinical outcomes.",
    "definition": "A core rule embedded within an Allocation Policy that gives priority to recipients located in the same geographic region as the donor. [cite_start]This principle is implemented by matching the donor's region with the recipient's `allc_region`[cite: 72]. The primary goals are to ensure equitable organ access for the local community and to improve medical outcomes by minimizing the Cold Ischemia time associated with long-distance transport."
  },
  {
    "id": 37,
    "knowledge": "Multi-Organ Transplant",
    "description": "A complex surgical procedure where a recipient receives two or more organs from a single donor.",
    "definition": "A transplant involving multiple organs (e.g., heart-lung, kidney-pancreas). Prioritization and allocation for these cases are highly complex, considering the significant need of the recipient and the impact on the organ pool for other patients."
  },
  {
    "id": 38,
    "knowledge": "Post-Transplant Monitoring",
    "description": "The ongoing medical surveillance of a recipient after receiving a transplant to ensure graft survival and manage complications.",
    "definition": "A comprehensive care plan that includes regular lab tests, imaging, and clinical assessments to monitor organ function, detect early signs of rejection, and manage immunosuppressive medications."
  },
  {
    "id": 39,
    "knowledge": "Viral Infection Status",
    "description": "Screening of donors and recipients for key viral infections that can be transmitted or reactivated during transplantation.",
    "definition": "Testing for viruses such as Cytomegalovirus (CMV), Epstein-Barr Virus (EBV), and Hepatitis. The Viral Infection Status of both donor and recipient is critical for assessing infection risk and planning post-transplant prophylactic treatment."
  },
  {
    "id": 40,
    "knowledge": "Body Mass Index (BMI) Categories",
    "description": "Illustrates the standard weight status categories based on BMI values.",
    "definition": "BMI provides a general indicator of body fatness. A value < 18.5 is considered underweight, 18.5-24.9 is normal weight, 25.0-29.9 is overweight, and > 30.0 indicates obesity. This is a factor in Size Compatibility Score."
  },
  {
    "id": 41,
    "knowledge": "Serum Creatinine Levels",
    "description": "Illustrates how serum creatinine levels reflect kidney function.",
    "definition": "A waste product from muscle metabolism, cleared by the kidneys. Normal values are typically 0.7-1.3 mg/dL. A high value, such as 2.5 mg/dL, suggests impaired kidney function, which is a key component of the Renal Function Score."
  },
  {
    "id": 42,
    "knowledge": "Glomerular Filtration Rate (GFR) Values",
    "description": "Illustrates the stages of kidney function based on GFR values.",
    "definition": "GFR measures how well the kidneys are filtering blood. A GFR > 90 mL/min/1.73m\u00b2 is considered normal. A GFR of 30-59 indicates moderate kidney disease, and a GFR < 15 signifies kidney failure."
  },
  {
    "id": 43,
    "knowledge": "Panel Reactive Antibody (PRA) Score Interpretation",
    "description": "Illustrates the meaning of different PRA score percentages.",
    "definition": "A PRA score reflects a recipient's sensitization level. A score of 0-10% indicates low sensitization, making it easier to find a compatible donor. A score > 80% indicates high Immunological Sensitization, meaning the patient is likely to be incompatible with over 80% of potential donors."
  },
  {
    "id": 44,
    "knowledge": "HLA Mismatch Levels",
    "description": "Illustrates the significance of the number of HLA mismatches.",
    "definition": "The number of mismatches impacts rejection risk. A '0-mismatch' is a perfect HLA match and is ideal. A '6-mismatch' is a complete mismatch across the A, B, and DR loci, representing the highest immunological barrier outside of ABO or positive crossmatch issues."
  },
  {
    "id": 45,
    "knowledge": "Medical Urgency Tiers",
    "description": "Illustrates the hierarchy of transplant urgency statuses.",
    "definition": "Patients are prioritized based on their risk of dying while on the waitlist. Status 1A is the highest urgency, reserved for critically ill patients in the ICU. Status 1B is a lower, but still urgent, category. Lower statuses (e.g., Status 2) are for more stable patients."
  },
  {
    "id": 46,
    "knowledge": "Crossmatch Results",
    "description": "Illustrates the critical outcomes of a crossmatch test.",
    "definition": "A 'Negative' result means no pre-formed donor-specific antibodies were detected, and the transplant can proceed. A 'Positive' result indicates the presence of these antibodies, making transplant highly risky or contraindicated due to the high chance of hyperacute rejection."
  },
  {
    "id": 47,
    "knowledge": "Cause of Death Impact",
    "description": "Illustrates how a donor's cause of death can affect organ quality.",
    "definition": "The mechanism of death influences organ viability. For example, death due to Anoxia (oxygen deprivation) can compromise the function of oxygen-sensitive organs like the heart and kidneys. In contrast, death from head trauma may leave abdominal organs in optimal condition."
  },
  {
    "id": 48,
    "knowledge": "Cost-Effectiveness Thresholds",
    "description": "Illustrates typical thresholds for considering a medical intervention as cost-effective.",
    "definition": "A common benchmark for the Cost-Effectiveness Ratio (CER) in the US is $50,000 to $150,000 per Quality-Adjusted Life Year (QALY) gained. Interventions below this threshold are generally considered a good value."
  },
  {
    "id": 49,
    "knowledge": "Liver Function Test (LFT) Values",
    "description": "Illustrates how LFT results can indicate liver health.",
    "definition": "Key markers like ALT and AST assess liver cell injury. Normal ranges are typically below 40-50 U/L. Elevated levels, such as an ALT of 200 U/L, can indicate significant liver inflammation or damage, affecting a donor organ's suitability."
  },
  {
    "id": 50,
    "knowledge": "Comprehensive Match Quality Score",
    "description": "A holistic meta-score that aggregates various sub-scores to represent the overall quality of a potential donor-recipient match.",
    "definition": "A weighted composite index integrating multiple factors. The score is calculated as: $S_{match} = 0.4 S_{immune} + 0.2 S_{age} - 0.3 S_{surgical} + 0.1 I_{logistics}$, using the Immunological Compatibility Score, Age Compatibility Score, Surgical Risk Score, and Logistical Feasibility Index."
  },
  {
    "id": 51,
    "knowledge": "Antibody-Mediated Rejection (AMR) Risk Stratification",
    "description": "A system for categorizing a recipient's risk of developing antibody-mediated rejection based on their immunological profile.",
    "definition": "A risk classification system. For recipients who have a 'Positive' crossmatch result, the 'High Risk' category is defined by meeting two concurrent criteria: having a Panel Reactive Antibody (PRA) score of 80 or greater AND having a 'Positive' donor-specific antibody (DSA) status. Recipients not meeting these criteria are considered 'Standard Risk'."
  },
  {
    "id": 52,
    "knowledge": "Net Health Benefit Score",
    "description": "Calculates the overall expected health gain for a recipient from a transplant, balancing survival benefits against procedural risks and quality of life.",
    "definition": "A score representing the projected net outcome, calculated by offsetting the anticipated Quality-Adjusted Life Year (QALY) gain with the risks. The formula is: $S_{NHB} = (EGS \\times QALY_{gain}) - (S_{surgical} \\times 0.2)$, where EGS is the Expected Graft Survival score."
  },
  {
    "id": 53,
    "knowledge": "Marginal Donor Acceptance Criteria",
    "description": "A set of clinical guidelines for evaluating and accepting organs from donors who do not meet ideal criteria but are not classified as standard High-Risk Donors.",
    "definition": "A nuanced decision framework applied to 'extended criteria' donors. These donors may exhibit factors like advanced age (significant Donor-Recipient Age Difference), borderline organ function (sub-optimal Renal Function Score), or certain comorbidities. Acceptance is based on a risk-benefit analysis, weighing the organ's imperfections against the recipient's urgent medical need and the scarcity of ideal organs."
  },
  {
    "id": 54,
    "knowledge": "Immunosuppression Protocol Tiers",
    "description": "Illustrates how a patient's immunological risk profile dictates the intensity of the required post-transplant immunosuppressive drug regimen.",
    "definition": "A tiered therapeutic strategy based on risk. A patient with a high Immunological Compatibility Score and low AMR risk (as per Antibody-Mediated Rejection (AMR) Risk Stratification) might receive a standard 'Maintenance Therapy' (e.g., a three-drug cocktail). Conversely, a patient with a low compatibility score and high AMR risk would require aggressive 'Induction Therapy' (e.g., using potent biologic agents) followed by intensive maintenance."
  }
]

